def mask_kotlin(text: str) -> str:
    """Mask comments and string/char literals while preserving offsets/newlines."""
    out = list(text)
    i, n = 0, len(text)
    state = "code"
    while i < n:
        if state == "code":
            if text.startswith("//", i):
                out[i:i+2] = "  "
                i += 2
                state = "line"
                continue
            if text.startswith("/*", i):
                out[i:i+2] = "  "
                i += 2
                state = "block"
                depth = 1
                while i < n and depth:
                    if text.startswith("/*", i):
                        out[i:i+2] = "  "
                        depth += 1
                        i += 2
                    elif text.startswith("*/", i):
                        out[i:i+2] = "  "
                        depth -= 1
                        i += 2
                    else:
                        if text[i] != "\n":
                            out[i] = " "
                        i += 1
                state = "code"
                continue
            if text.startswith('"""', i):
                out[i:i+3] = "   "
                i += 3
                while i < n and not text.startswith('"""', i):
                    if text[i] != "\n":
                        out[i] = " "
                    i += 1
                if i < n:
                    out[i:i+3] = "   "
                    i += 3
                continue
            if text[i] in ('"', "'"):
                quote = text[i]
                out[i] = " "
                i += 1
                while i < n:
                    ch = text[i]
                    if ch == "\\":
                        out[i] = " "
                        if i + 1 < n and text[i+1] != "\n":
                            out[i+1] = " "
                        i += 2
                    elif ch == quote:
                        out[i] = " "
                        i += 1
                        break
                    else:
                        if ch != "\n":
                            out[i] = " "
                        i += 1
                continue
            i += 1
        elif state == "line":
            if text[i] == "\n":
                state = "code"
            else:
                out[i] = " "
            i += 1
    return "".join(out)

def extract_text(path, raw):
    suffix = path.suffix.lower()

    if suffix in (".txt", ".md"):
        return raw.decode("utf-8-sig", errors="strict")

    if suffix in (".html", ".htm"):
        parser = TextExtractor()
        parser.feed(raw.decode("utf-8-sig", errors="strict"))
        return "\n".join(parser.parts)

    if suffix == ".json":
        return extract_json_strings(
            json.loads(raw.decode("utf-8-sig"))
        )

    if suffix == ".jsonl":
        parts = []
        for line_number, line in enumerate(
            raw.decode("utf-8-sig").splitlines(), 1
        ):
            if not line.strip():
                continue
            try:
                parts.append(
                    extract_json_strings(json.loads(line))
                )
            except json.JSONDecodeError as exc:
                raise ValueError(
                    f"Invalid JSONL line {line_number}: {exc}"
                ) from exc
        return "\n".join(parts)

    if suffix == ".csv":
        text = raw.decode("utf-8-sig", errors="strict")
        rows = csv.reader(text.splitlines())
        return "\n".join(
            " | ".join(cell.strip() for cell in row if cell.strip())
            for row in rows
        )

    raise ValueError(f"Unsupported file type: {suffix}")

