def normalize(text: str) -> str:
    text = text.strip().lower()
    text = ARABIC_DIACRITICS.sub("", text)
    text = text.replace("ـ", "")
    return text.translate(str.maketrans({
        "أ": "ا", "إ": "ا", "آ": "ا", "ى": "ي"
    }))

