def teach(self, topic: str, content: str) -> dict:
        topic_norm = topic.strip().lower()
        content_hash = hashlib.sha256(content.encode("utf-8")).hexdigest()
        import time
        now = time.time()
        try:
            cur = self.db.execute(
                "INSERT INTO knowledge(topic, topic_norm, content, content_hash, lang, source, status, confidence, support, hits, feedback, created_at, updated_at) "
                "VALUES (?, ?, ?, ?, 'ar', 'owner', 'verified', 0.9, 1, 0, 0, ?, ?)",
                (topic, topic_norm, content, content_hash, now, now)
            )
            return {"id": cur.lastrowid, "topic": topic, "status": "verified", "action": "created"}
        except sqlite3.IntegrityError:
            return {"status": "exists", "topic": topic}

def parse_typescript_files(files):
    entities, relations, dependencies, errors = [], [], [], []
    for path, content, digest in files:
        payload = {
            "root": str(ROOT),
            "files": [{
                "path": path.relative_to(ROOT).as_posix(),
                "text": content,
            }],
        }
        try:
            proc = subprocess.run(
                ["node", "-e", TS_SCRIPT],
                input=json.dumps(payload),
                text=True,
                capture_output=True,
                cwd=ROOT,
                timeout=60,
            )
        except Exception as exc:
            errors.append({
                "path": path.relative_to(ROOT).as_posix(),
                "language": "typescript",
                "error_type": type(exc).__name__,
                "message": str(exc),
            })
            continue

        if proc.returncode != 0:
            errors.append({
                "path": path.relative_to(ROOT).as_posix(),
                "language": "typescript",
                "error_type": "CompilerApiError",
                "message": proc.stderr[-2000:],
            })
            continue

        try:
            parsed = json.loads(proc.stdout)
        except json.JSONDecodeError as exc:
            errors.append({
                "path": path.relative_to(ROOT).as_posix(),
                "language": "typescript",
                "error_type": "InvalidCompilerOutput",
                "message": str(exc),
            })
            continue

        errors.extend(parsed.get("errors", []))
        for bucket_name, category, destination in (
            ("entities", "entity", entities),
            ("relations", "relation", relations),
            ("dependencies", "dependency", dependencies),
        ):
            for item in parsed.get(bucket_name, []):
                destination.append(make_record(
                    category,
                    "typescript",
                    item["kind"],
                    item["qualified_name"],
                    item["snippet"],
                    path,
                    digest,
                    item["line_start"],
                    item["line_end"],
                    "typescript.compiler_api",
                    "high",
                    item.get("extra"),
                ))
    return entities, relations, dependencies, errors

