def encode(self, text, add_bos=False, add_eos=False):
        if not isinstance(text, str):
            raise TypeError("text must be str")
        ids = [b + self.BYTE_OFFSET for b in text.encode("utf-8", errors="strict")]
        if add_bos:
            ids.insert(0, self.BOS)
        if add_eos:
            ids.append(self.EOS)
        return ids

search(query: string): Array<{ title: string; content: string; score: number }> {
    if (!fs.existsSync(KB_DIR)) return [];
    const files = fs.readdirSync(KB_DIR);
    const results = [];
    const lowerQuery = query.toLowerCase();

    for (const file of files) {
      if (!file.endsWith('.json')) continue;
      try {
        const data = JSON.parse(fs.readFileSync(path.join(KB_DIR, file), 'utf-8'));
        const contentLower = data.content.toLowerCase();
        const titleLower = data.title.toLowerCase();
        let score = 0;
        if (titleLower.includes(lowerQuery)) score += 10;
        if (contentLower.includes(lowerQuery)) score += 5;
        if (score > 0) {
          results.push({ title: data.title, content: data.content, score });
        }
      } catch (e) {
        // تجاهل الملفات التالفة
      }
    }
    return results.sort((a, b) => b.score - a.score);
  }

function splitIntoChunks(
  text: string,
  chunkSize = 900,
  overlap = 120
): string[] {
  const cleaned = text.replace(/\r\n/g, "\n").trim();

  if (!cleaned) return [];

  const chunks: string[] = [];
  let start = 0;

  while (start < cleaned.length) {
    let end = Math.min(start + chunkSize, cleaned.length);

    if (end < cleaned.length) {
      const boundary = cleaned.lastIndexOf(" ", end);
      if (boundary > start + chunkSize * 0.6) {
        end = boundary;
      }
    }

    const part = cleaned.slice(start, end).trim();

    if (part) chunks.push(part);
    if (end >= cleaned.length) break;

    start = Math.max(start + 1, end - overlap);
  }

  return chunks;
}

