async getModelStatus(): Promise<GatewayModelStatus> {
    const controller = new AbortController();
    const timer = setTimeout(() => controller.abort(), 5_000);

    try {
      const response = await this.fetchImpl(
        `${this.baseUrl}/api/model/status`,
        {
          method: "GET",
          headers: { Accept: "application/json" },
          signal: controller.signal
        }
      );

      if (!response.ok) {
        throw new CoordinatorError(
          `Local gateway status returned HTTP ${response.status}`,
          "GATEWAY_STATUS_FAILED",
          503
        );
      }

      return await response.json() as GatewayModelStatus;
    } catch (error) {
      if (error instanceof CoordinatorError) throw error;

      throw new CoordinatorError(
        error instanceof Error && error.name === "AbortError"
          ? "Local gateway status timed out"
          : "Local gateway is unavailable",
        "GATEWAY_UNAVAILABLE",
        503
      );
    } finally {
      clearTimeout(timer);
    }
  }

register(tool: RegisteredTool): void {
    if (!tool.name.trim()) {
      throw new CoordinatorError(
        "Tool name is required",
        "INVALID_TOOL",
        400
      );
    }

    if (this.tools.has(tool.name)) {
      throw new CoordinatorError(
        `Tool already registered: ${tool.name}`,
        "DUPLICATE_TOOL",
        409
      );
    }

    this.tools.set(tool.name, tool);
  }

def learning_rate_at(step, total_steps, base_lr, warmup_steps):
    if warmup_steps > 0 and step < warmup_steps:
        return base_lr * float(step + 1) / float(warmup_steps)

    decay_steps = max(1, total_steps - warmup_steps)
    progress = min(
        1.0,
        max(0.0, (step - warmup_steps) / decay_steps)
    )
    cosine = 0.5 * (1.0 + math.cos(math.pi * progress))

    return base_lr * (0.1 + 0.9 * cosine)

export class IntentRouter {
  route(request: AnalyzedRequest): RouteDecision {
    if (request.explicitEngine === "agent") {
      return {
        engineId: "agent",
        intent: request.intent,
        executionMode: "local_text"
      };
    }

    const engineId: SupportedEngine = request.explicitEngine
      ?? request.intent;

    return {
      engineId,
      intent: request.intent,
      executionMode: "local_text"
    };
  }
}

