def main():
    OUTPUT.parent.mkdir(
        parents=True,
        exist_ok=True,
    )

    # Never overwrite an existing dataset.
    if OUTPUT.exists():
        raise FileExistsError(
            f"Refusing to overwrite existing dataset: {OUTPUT}"
        )

    prompts = set()
    pairs = set()
    rows = []

    for language, instruction, response in DATA:
        instruction = instruction.strip()
        response = response.strip()

        if not instruction or not response:
            raise ValueError("Empty instruction or response")

        normalized_prompt = normalize(instruction)
        normalized_pair = (
            normalized_prompt,
            normalize(response),
        )

        if normalized_prompt in prompts:
            raise ValueError(
                f"Duplicate prompt detected: {instruction}"
            )

        if normalized_pair in pairs:
            raise ValueError(
                f"Duplicate conversation detected: {instruction}"
            )

        prompts.add(normalized_prompt)
        pairs.add(normalized_pair)

        rows.append({
            "instruction": instruction,
            "response": response,
            "language": language,
        })

    if len(rows) < 150:
        raise ValueError(
            f"Dataset too small: {len(rows)} records"
        )

    arabic_count = sum(
        row["language"] == "ar" for row in rows
    )

    english_count = sum(
        row["language"] == "en" for row in rows
    )

    if arabic_count < 50 or english_count < 50:
        raise ValueError(
            "Both languages must have at least 50 records"
        )

    content = "".join(
        json.dumps(
            row,
            ensure_ascii=False,
        ) + "\n"
        for row in rows
    )

    # Write atomically without replacing an existing target.
    temporary = OUTPUT.with_name(
        OUTPUT.name + ".tmp"
    )

    if temporary.exists():
        raise FileExistsError(
            f"Temporary output already exists: {temporary}"
        )

    try:
        with temporary.open(
            "x",
            encoding="utf-8",
            newline="\n",
        ) as stream:
            stream.write(content)
            stream.flush()

        # Recheck target before publication.
        if OUTPUT.exists():
            raise FileExistsError(OUTPUT)

        temporary.rename(OUTPUT)

    except Exception:
        # Keep the temporary file for inspection if publication fails.
        raise

    digest = hashlib.sha256(
        OUTPUT.read_bytes()
    ).hexdigest()

    print("LAZAYNOVA V3 DATASET CREATED")
    print("Path:", OUTPUT)
    print("Total records:", len(rows))
    print("Arabic records:", arabic_count)
    print("English records:", english_count)
    print("Unique prompts:", len(prompts))
    print("Unique pairs:", len(pairs))
    print("SHA256:", digest)
    print("Dataset bytes:", OUTPUT.stat().st_size)

export function indexDocument(input: {
  title: string;
  text: string;
  source?: string;
}): {
  documentId: string;
  chunksIndexed: number;
} {
  if (!input.title.trim()) {
    throw new Error("Document title is required");
  }

  if (!input.text.trim()) {
    throw new Error("Document text is required");
  }

  if (input.text.length > 500_000) {
    throw new Error("Document exceeds 500000 characters");
  }

  const documentId = crypto.randomUUID();
  const now = new Date().toISOString();

  const chunks = splitIntoChunks(input.text).map(
    (text): KnowledgeChunk => ({
      id: crypto.randomUUID(),
      documentId,
      title: input.title.trim().slice(0, 200),
      source: (input.source || input.title).slice(0, 500),
      text,
      terms: [...new Set(tokenize(text))],
      createdAt: now
    })
  );

  writeDb([...readDb(), ...chunks]);

  return {
    documentId,
    chunksIndexed: chunks.length
  };
}

class ByteTokenizer:
    PAD, UNK, BOS, EOS = 0, 1, 2, 3
    BYTE_OFFSET = 4
    VOCAB_SIZE = 260

    def encode(self, text, add_bos=False, add_eos=False):
        if not isinstance(text, str):
            raise TypeError("text must be str")
        ids = [b + self.BYTE_OFFSET for b in text.encode("utf-8", errors="strict")]
        if add_bos:
            ids.insert(0, self.BOS)
        if add_eos:
            ids.append(self.EOS)
        return ids

    def decode(self, tokens, errors="strict"):
        if errors not in ("strict", "ignore"):
            raise ValueError("errors must be strict or ignore")
        data = bytearray()
        for token in tokens:
            token = int(token)
            if self.BYTE_OFFSET <= token < self.VOCAB_SIZE:
                data.append(token - self.BYTE_OFFSET)
            elif token in (self.PAD, self.UNK, self.BOS, self.EOS):
                continue
            else:
                raise ValueError(f"token id outside vocabulary: {token}")
        return data.decode("utf-8", errors=errors)

    def get_config(self):
        return {"type":"native_utf8_byte","vocab_size":self.VOCAB_SIZE,
                "pad_token":self.PAD,"unk_token":self.UNK,
                "bos_token":self.BOS,"eos_token":self.EOS}

def write_jsonl(path, records):
    temporary = path.with_suffix(path.suffix + ".tmp")

    with temporary.open("x", encoding="utf-8") as handle:
        for record in records:
            handle.write(
                json.dumps(record, ensure_ascii=False) + "\n"
            )

