def validate_examples(records, context_length):
    tokenizer = ByteTokenizer()
    lengths = []

    for index, record in enumerate(records):
        inputs, targets = encode_pair(record, tokenizer)
        if len(inputs) != len(targets):
            raise RuntimeError("Input/target length mismatch")
        if len(inputs) > context_length:
            raise ValueError(
                f"Record {index} requires {len(inputs)} input tokens; "
                f"context limit is {context_length}. "
                "No truncation is permitted."
            )
        if any(
            target != IGNORE_INDEX
            and not 0 <= target < tokenizer.VOCAB_SIZE
            for target in targets
        ):
            raise ValueError(f"Invalid target token in record {index}")
        lengths.append(len(inputs))

    return {
        "count": len(lengths),
        "min_tokens": min(lengths),
        "max_tokens": max(lengths),
        "average_tokens": sum(lengths) / len(lengths),
    }

async complete(
    prompt: string,
    maxTokens: number
  ): Promise<GatewayCompletion> {
    // One bounded retry for temporary upstream gateway errors only.
    const maxRetries = 1;

    for (let attempt = 0; attempt <= maxRetries; attempt++) {
      const controller = new AbortController();
      const timer = setTimeout(
        () => controller.abort(),
        90_000
      );

      try {
        const response = await this.fetchImpl(
          `${this.baseUrl}/v1/chat/completions`,
          {
            method: "POST",
            headers: { "Content-Type": "application/json" },
            body: JSON.stringify({
              model: "LAZAYNOVA-L3-native-v2",
              messages: [{ role: "user", content: prompt }],
              temperature: 0,
              max_tokens: maxTokens,
              stream: false
            }),
            signal: controller.signal
          }
        );

        if (
          (response.status === 502 || response.status === 504)
          && attempt < maxRetries
        ) {
          continue;
        }

        if (!response.ok) {
          throw new CoordinatorError(
            `Local inference returned HTTP ${response.status}`,
            response.status === 503
              ? "MODEL_NOT_READY"
              : "INFERENCE_FAILED",
            response.status === 503 ? 503 : 502
          );
        }

        const data = await response.json() as ChatCompletionPayload;
        const answer = data.choices?.[0]?.message?.content?.trim();

        if (!answer) {
          throw new CoordinatorError(
            data.error?.message || "Local model returned an empty answer",
            "EMPTY_MODEL_OUTPUT",
            502
          );
        }

        return {
          model: "LAZAYNOVA-L3-native-v2",
          answer
        };
      } catch (error) {
        if (error instanceof CoordinatorError) throw error;

        throw new CoordinatorError(
          error instanceof Error && error.name === "AbortError"
            ? "Local inference timed out after 90 seconds"
            : "Local inference connection failed",
          error instanceof Error && error.name === "AbortError"
            ? "INFERENCE_TIMEOUT"
            : "GATEWAY_UNAVAILABLE",
          503
        );
      } finally {
        clearTimeout(timer);
      }
    }

    throw new CoordinatorError(
      "Local inference retry limit reached",
      "RETRY_LIMIT_REACHED",
      503
    );
  }

