    const nextScope = (
      (ts.isClassDeclaration(node) || ts.isInterfaceDeclaration(node) ||
       ts.isFunctionDeclaration(node) || ts.isMethodDeclaration(node)) && name
    ) ? q : scope;
    ts.forEachChild(node, child=>walk(child, nextScope));
  }
  walk(sf, [file.path]);
