class FeedForward(nn.Module):
    def __init__(self, config):
        super().__init__()
        dim, hidden = int(config["d_model"]), int(config["ff_dim"])
        self.net = nn.Sequential(nn.Linear(dim, hidden), nn.GELU(),
                                 nn.Linear(hidden, dim),
