  documentId: string;
  title: string;
  source: string;
  chunks: number;
}> {
  const groups = new Map<string, {
    documentId: string;
    title: string;
    source: string;
    chunks: number;
  }>();

  for (const chunk of readDb()) {
    const existing = groups.get(chunk.documentId);

    if (existing) {
      existing.chunks++;
    } else {
      groups.set(chunk.documentId, {
        documentId: chunk.documentId,
        title: chunk.title,
        source: chunk.source,
        chunks: 1
      });
    }
  }

  return [...groups.values()];
}

